import { useLayoutEffect } from "react";

const FOCUS_SELECTOR = "[data-hash-focus]";

export function prefersReducedMotion(): boolean {
  if (typeof window.matchMedia !== "function") {
    return false;
  }
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function idFromHash(hash: string): string | null {
  const raw = hash.startsWith("#") ? hash.slice(1) : hash;
  if (!raw) {
    return null;
  }
  try {
    return decodeURIComponent(raw);
  } catch {
    return null;
  }
}

function hashElement(hash: string): HTMLElement | null {
  const id = idFromHash(hash);
  if (!id) {
    return null;
  }
  const target = document.getElementById(id);
  return target instanceof HTMLElement ? target : null;
}

export function scrollToHash(
  hash: string = window.location.hash,
  behavior?: ScrollBehavior
): boolean {
  const target = hashElement(hash);
  if (!target) {
    return false;
  }
  const chosen = behavior ?? (prefersReducedMotion() ? "auto" : "smooth");
  target.scrollIntoView({ behavior: chosen, block: "start" });
  return true;
}

/**
 * Move focus to the section heading. Headings are not editable, so this
 * does not open the mobile keyboard the way focusing an input would.
 */
export function focusHash(hash: string = window.location.hash): boolean {
  const target = hashElement(hash);
  if (!target) {
    return false;
  }
  const focusTarget = target.matches(FOCUS_SELECTOR)
    ? target
    : target.querySelector<HTMLElement>(FOCUS_SELECTOR) ?? target;
  if (focusTarget.tabIndex < 0) {
    focusTarget.tabIndex = -1;
  }
  focusTarget.focus({ preventScroll: true });
  return true;
}

export function revealHash(hash: string = window.location.hash): boolean {
  const scrolled = scrollToHash(hash);
  focusHash(hash);
  return scrolled;
}

function isPlainHashClick(event: MouseEvent): HTMLAnchorElement | null {
  if (
    event.defaultPrevented ||
    event.button !== 0 ||
    event.metaKey ||
    event.ctrlKey ||
    event.shiftKey ||
    event.altKey
  ) {
    return null;
  }
  const node = event.target;
  if (!(node instanceof Element)) {
    return null;
  }
  const anchor = node.closest("a[href]");
  if (!(anchor instanceof HTMLAnchorElement)) {
    return null;
  }
  const href = anchor.getAttribute("href");
  if (!href || !href.startsWith("#")) {
    return null;
  }
  if (!hashElement(href)) {
    return null;
  }
  return anchor;
}

function targetAligned(hash: string): boolean {
  const target = hashElement(hash);
  if (!target) {
    return true;
  }
  const margin = Number.parseFloat(window.getComputedStyle(target).scrollMarginTop) || 0;
  return Math.abs(target.getBoundingClientRect().top - margin) < 32;
}

/**
 * Direct loads paint after the browser's first hash jump, and images above
 * the target can move it again. Re-scroll without focusing an input.
 * A wheel, touch, or key from the reader stops the correction.
 */
export function useHashScroll(): void {
  useLayoutEffect(() => {
    let stopCorrection = false;
    const stop = () => {
      stopCorrection = true;
    };
    const correct = () => {
      const hash = window.location.hash;
      if (stopCorrection || !idFromHash(hash) || targetAligned(hash)) {
        return;
      }
      scrollToHash(hash, "auto");
    };

    revealHash();
    const delays = [50, 250, 700, 1400].map((ms) => window.setTimeout(correct, ms));
    const images = Array.from(document.images);
    images.forEach((img) => {
      if (!img.complete) {
        img.addEventListener("load", correct);
      }
    });

    const onHashChange = () => {
      revealHash();
    };

    const onLoad = () => {
      correct();
    };

    const onClick = (event: MouseEvent) => {
      const anchor = isPlainHashClick(event);
      if (!anchor) {
        return;
      }
      const href = anchor.getAttribute("href") ?? "";
      event.preventDefault();
      const nextHash = href.startsWith("#") ? href : `#${href}`;
      if (window.location.hash !== nextHash) {
        window.history.pushState(null, "", nextHash);
      }
      revealHash(nextHash);
    };

    window.addEventListener("hashchange", onHashChange);
    window.addEventListener("popstate", onHashChange);
    window.addEventListener("load", onLoad);
    window.addEventListener("wheel", stop, { passive: true });
    window.addEventListener("touchstart", stop, { passive: true });
    window.addEventListener("keydown", stop);
    document.addEventListener("click", onClick);
    return () => {
      delays.forEach((id) => window.clearTimeout(id));
      images.forEach((img) => img.removeEventListener("load", correct));
      window.removeEventListener("hashchange", onHashChange);
      window.removeEventListener("popstate", onHashChange);
      window.removeEventListener("load", onLoad);
      window.removeEventListener("wheel", stop);
      window.removeEventListener("touchstart", stop);
      window.removeEventListener("keydown", stop);
      document.removeEventListener("click", onClick);
    };
  }, []);
}
