import { Button, Stack, Text } from "@chakra-ui/react";
import React from "react";
import { APP_STORE_URL, PLAY_STORE_URL } from "../content/links";

const buttonProps = {
  as: "a" as const,
  target: "_blank",
  rel: "noopener noreferrer",
  bg: "#FF5555",
  color: "black",
  h: "auto",
  minH: "48px",
  px: 5,
  py: 3,
  borderRadius: "xl",
  display: "inline-flex",
  flexDirection: "column" as const,
  alignItems: "flex-start",
  justifyContent: "center",
  _hover: { bg: "#ff7070", textDecoration: "none" },
  _focusVisible: { outline: "3px solid white", outlineOffset: "3px" },
};

/**
 * The accessible name starts with the visible label, in the same order.
 * Lighthouse rejects an aria-label that inserts words the screen does not show.
 */
function StoreLink({ href, store }: { href: string; store: string }) {
  const visible = `Get No DNF ${store}`;
  return (
    <Button {...buttonProps} href={href} aria-label={`${visible} (opens in a new tab)`}>
      <Text as="span" fontSize="md" fontWeight="bold" lineHeight="short">
        Get No DNF
      </Text>
      <Text as="span" fontSize="sm" fontWeight="medium">
        {` ${store}`}
      </Text>
    </Button>
  );
}

const StoreButtons = () => {
  return (
    <Stack direction={{ base: "column", sm: "row" }} spacing={3} align="stretch">
      <StoreLink href={APP_STORE_URL} store="App Store" />
      <StoreLink href={PLAY_STORE_URL} store="Google Play" />
    </Stack>
  );
};

export default StoreButtons;
