import { Box, Heading, Text } from "@chakra-ui/react";
import React from "react";

type SectionProps = {
  id: string;
  title: string;
  eyebrow?: string;
  plainHeading?: boolean;
  children: React.ReactNode;
};

const Section = ({ id, title, eyebrow, plainHeading = false, children }: SectionProps) => {
  const headingId = `${id}-heading`;

  return (
    <Box
      as="section"
      id={id}
      aria-labelledby={headingId}
      w="100%"
      px={{ base: 4, md: 8 }}
      py={{ base: 12, md: 20 }}
    >
      <Box maxW="72rem" mx="auto">
        {eyebrow ? (
          <Text
            color="#FF5555"
            fontSize="sm"
            fontWeight="bold"
            letterSpacing="0.08em"
            textTransform="uppercase"
            mb={3}
          >
            {eyebrow}
          </Text>
        ) : null}
        <Heading
          as="h2"
          id={headingId}
          tabIndex={-1}
          data-hash-focus
          fontSize={{ base: "2xl", md: "4xl" }}
          fontWeight="bold"
          fontStyle={plainHeading ? "normal" : "italic"}
          lineHeight="shorter"
          mb={6}
        >
          {title}
        </Heading>
        {children}
      </Box>
    </Box>
  );
};

export default Section;
